using Microsoft.AspNetCore.Mvc; using System.Text.Json;
namespace RaceDay.Web;
public class HomeController(ApiClient api):Controller { public async Task<IActionResult> Index(string? type,string? location){var events=await api.Get<JsonElement[]>("api/events")??[];var filtered=events.Where(e=>(string.IsNullOrWhiteSpace(type)||e.GetProperty("eventType").GetString()==type)&&(string.IsNullOrWhiteSpace(location)||e.GetProperty("location").GetString()!.Contains(location,StringComparison.OrdinalIgnoreCase))).ToArray();return View(filtered);} public async Task<IActionResult> Details(int id){var item=await api.Get<JsonElement>($"api/events/{id}");return item.ValueKind==JsonValueKind.Undefined?NotFound():View(item);} }
public class AccountController(ApiClient api):Controller { public IActionResult Login()=>View(); public IActionResult Register()=>View(new RegisterViewModel()); [HttpPost] public async Task<IActionResult> Register(RegisterViewModel m){if(!ModelState.IsValid)return View(m);var r=await api.SendJson(HttpMethod.Post,"api/auth/register",m);if(!r.IsSuccessStatusCode){ModelState.AddModelError("","Registration failed. Check the required details and try a unique username/email.");return View(m);}return await CompleteLogin(r,"Your account is ready.");} [HttpPost] public async Task<IActionResult> Login(string usernameOrEmail,string password){var r=await api.SendJson(HttpMethod.Post,"api/auth/login",new{usernameOrEmail,password});if(!r.IsSuccessStatusCode){ModelState.AddModelError("","Invalid username/email or password.");return View();}return await CompleteLogin(r,null);} async Task<IActionResult> CompleteLogin(HttpResponseMessage r,string? message){var x=JsonDocument.Parse(await r.Content.ReadAsStringAsync()).RootElement;HttpContext.Session.SetString("token",x.GetProperty("token").GetString()!);HttpContext.Session.SetString("role",x.GetProperty("role").GetString()!);HttpContext.Session.SetString("username",x.GetProperty("username").GetString()!);if(message is not null)TempData["Success"]=message;return RedirectToAction("Index","Home");} public IActionResult Logout(){HttpContext.Session.Clear();return RedirectToAction("Index","Home");} }
public class ParticipantController(ApiClient api):Controller { bool Allowed()=>HttpContext.Session.GetString("role")=="Participant"&&!string.IsNullOrWhiteSpace(HttpContext.Session.GetString("token")); IActionResult Login()=>RedirectToAction("Login","Account"); public async Task<IActionResult> Enrollments(){if(!Allowed())return Login();return View(await api.Get<JsonElement[]>("api/enrollments")??[]);} [HttpPost] public async Task<IActionResult> Enrol(int categoryId,int eventId){if(!Allowed())return Login();var r=await api.SendJson(HttpMethod.Post,"api/enrollments",new{categoryId});TempData[r.IsSuccessStatusCode?"Success":"Error"]=r.IsSuccessStatusCode?"You are enrolled. Your status is pending payment.":"We could not complete the enrolment. You may already be enrolled.";return RedirectToAction("Details","Home",new{id=eventId});} public async Task<IActionResult> Results(){if(!Allowed())return Login();return View(await api.Get<JsonElement[]>("api/results")??[]);} public async Task<IActionResult> Profile(){if(!Allowed())return Login();var p=await api.Get<JsonElement>("api/users/profile");if(p.ValueKind==JsonValueKind.Undefined)return Login();var x=p.GetProperty("participant");return View(new ProfileViewModel{FirstName=x.GetProperty("firstName").GetString(),LastName=x.GetProperty("lastName").GetString(),DateOfBirth=DateOnly.Parse(x.GetProperty("dateOfBirth").GetString()!),Gender=x.GetProperty("gender").GetString(),EmergencyContact=x.GetProperty("emergencyContact").GetString(),ProfilePictureUrl=x.TryGetProperty("profilePictureUrl",out var pic)?pic.GetString():null});} [HttpPost] public async Task<IActionResult> Profile(ProfileViewModel m){if(!Allowed())return Login();if(m.Picture is not null)m.ProfilePictureUrl=await api.Upload("api/images/profile-picture",m.Picture);var r=await api.SendJson(HttpMethod.Put,"api/users/profile",new{m.FirstName,m.LastName,m.DateOfBirth,m.Gender,m.EmergencyContact,m.ProfilePictureUrl});TempData[r.IsSuccessStatusCode?"Success":"Error"]=r.IsSuccessStatusCode?"Profile updated.":"Profile update failed.";return RedirectToAction(nameof(Profile));} }
public class OrganiserController(ApiClient api):Controller { bool Allowed()=>HttpContext.Session.GetString("role")=="Organiser"&&!string.IsNullOrWhiteSpace(HttpContext.Session.GetString("token")); IActionResult Login()=>RedirectToAction("Login","Account"); object EventPayload(EventViewModel m)=>new{m.EventName,m.Description,m.EventDate,m.Location,m.Distance,m.EventType,m.BannerImageUrl,m.Status}; public async Task<IActionResult> Dashboard(){if(!Allowed())return Login();return View(await api.Get<JsonElement[]>("api/organiser/events")??[]);} public async Task<IActionResult> Events(){if(!Allowed())return Login();return View(await api.Get<JsonElement[]>("api/organiser/events")??[]);} public IActionResult CreateEvent(){if(!Allowed())return Login();return View("EventForm",new EventViewModel());} [HttpPost] public async Task<IActionResult> CreateEvent(EventViewModel m){if(!Allowed())return Login();if(!ModelState.IsValid)return View("EventForm",m);if(m.Banner is not null)m.BannerImageUrl=await api.Upload("api/images/event-banner",m.Banner);var r=await api.SendJson(HttpMethod.Post,"api/events",EventPayload(m));TempData[r.IsSuccessStatusCode?"Success":"Error"]=r.IsSuccessStatusCode?"Event created.":"Could not create event.";return RedirectToAction(nameof(Events));} public async Task<IActionResult> EditEvent(int id){if(!Allowed())return Login();var e=await api.Get<JsonElement>($"api/events/{id}");if(e.ValueKind==JsonValueKind.Undefined)return NotFound();return View("EventForm",new EventViewModel{EventId=id,EventName=e.GetProperty("eventName").GetString()!,Description=e.GetProperty("description").GetString()!,EventDate=DateOnly.Parse(e.GetProperty("eventDate").GetString()!),Location=e.GetProperty("location").GetString()!,Distance=e.GetProperty("distance").GetDecimal(),EventType=e.GetProperty("eventType").GetString()!,Status=e.GetProperty("status").GetString(),BannerImageUrl=e.TryGetProperty("bannerImageUrl",out var b)?b.GetString():null});} [HttpPost] public async Task<IActionResult> EditEvent(EventViewModel m){if(!Allowed())return Login();if(m.Banner is not null)m.BannerImageUrl=await api.Upload("api/images/event-banner",m.Banner);var r=await api.SendJson(HttpMethod.Put,$"api/events/{m.EventId}",EventPayload(m));TempData[r.IsSuccessStatusCode?"Success":"Error"]=r.IsSuccessStatusCode?"Event updated.":"Could not update event.";return RedirectToAction(nameof(Events));} [HttpPost] public async Task<IActionResult> DeleteEvent(int id){if(!Allowed())return Login();await api.Delete($"api/events/{id}");return RedirectToAction(nameof(Events));} public async Task<IActionResult> Categories(int eventId){if(!Allowed())return Login();ViewBag.EventId=eventId;ViewBag.Categories=await api.Get<JsonElement[]>($"api/events/{eventId}/categories")??[];return View(new CategoryViewModel());} [HttpPost] public async Task<IActionResult> Categories(int eventId,CategoryViewModel m){if(!Allowed())return Login();if(ModelState.IsValid)await api.SendJson(HttpMethod.Post,$"api/events/{eventId}/categories",m);return RedirectToAction(nameof(Categories),new{eventId});} public async Task<IActionResult> Enrollments(int eventId){if(!Allowed())return Login();ViewBag.EventId=eventId;return View(await api.Get<JsonElement[]>($"api/events/{eventId}/enrollments")??[]);} [HttpPost] public async Task<IActionResult> RecordResult(ResultViewModel m,int eventId){if(!Allowed())return Login();await api.SendJson(HttpMethod.Post,"api/results",m);return RedirectToAction(nameof(Enrollments),new{eventId});} }
